package main

import "fmt"

func main() {
	// 1) Composite literal: allocate and populate in one expression.
	ages := map[string]int{
		"alice": 30,
		"bob":   25,
	}

	// 2) make(): allocate an empty, writable map (optionally presized).
	scores := make(map[string]int, 4)

	scores["alice"] = 90 // insert
	scores["alice"] = 95 // update (same key overwrites)
	scores["bob"]++      // missing key reads as 0, then becomes 1

	fmt.Println("alice age:", ages["alice"]) // 30
	fmt.Println("bob score:", scores["bob"]) // 1
	fmt.Println("count:", len(scores))       // 2

	// Missing key returns the ZERO value, not an error.
	fmt.Println("carol score:", scores["carol"]) // 0

	// comma-ok: distinguish "absent" from "present with zero value".
	if v, ok := scores["carol"]; ok {
		fmt.Println("carol present with", v)
	} else {
		fmt.Println("carol is absent") // this branch runs
	}
}

package main

import "fmt"

func main() {
	m := map[string]int{"x": 1, "y": 2}

	delete(m, "x")       // removes "x"
	delete(m, "missing") // no-op, never panics
	fmt.Println(m, "len =", len(m)) // map[y:2] len = 1

	// A nil map: declared but never made.
	var nm map[string]int
	fmt.Println("nil map read:", nm["anything"]) // 0 — reading is safe
	fmt.Println("nil map len:", len(nm))          // 0

	// Writing to a nil map PANICS at runtime.
	defer func() {
		if r := recover(); r != nil {
			fmt.Println("recovered:", r)
		}
	}()
	nm["key"] = 1 // panic: assignment to entry in nil map
}

package main

import (
	"fmt"
	"sort"
)

func main() {
	m := map[string]int{"banana": 3, "apple": 5, "cherry": 1}

	// Range order is RANDOMIZED — do not rely on it.
	fmt.Println("random order:")
	for k, v := range m {
		fmt.Printf("  %s=%d\n", k, v)
	}

	// Deterministic: collect keys, sort, then iterate.
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	fmt.Println("sorted order:")
	for _, k := range keys {
		fmt.Printf("  %s=%d\n", k, m[k])
	}
}

package main

import "fmt"

func main() {
	// struct{} value type stores no data — pure membership set.
	seen := make(map[string]struct{})

	visitors := []string{"alice", "bob", "alice", "carol", "bob"}
	var unique []string
	for _, name := range visitors {
		if _, ok := seen[name]; !ok {
			seen[name] = struct{}{} // add to set
			unique = append(unique, name)
		}
	}

	fmt.Println("unique visitors:", unique) // [alice bob carol]
	fmt.Println("distinct count:", len(seen)) // 3

	// Membership test via comma-ok.
	_, isMember := seen["bob"]
	fmt.Println("bob seen?", isMember) // true
}

package main

import (
	"fmt"
	"sync"
)

// SafeCounter guards a map with a read/write mutex.
type SafeCounter struct {
	mu sync.RWMutex
	m  map[string]int
}

func NewSafeCounter() *SafeCounter {
	return &SafeCounter{m: make(map[string]int)}
}

func (c *SafeCounter) Inc(key string) {
	c.mu.Lock()         // exclusive lock for writes
	c.m[key]++
	c.mu.Unlock()
}

func (c *SafeCounter) Get(key string) int {
	c.mu.RLock()        // shared lock for reads
	defer c.mu.RUnlock()
	return c.m[key]
}

func main() {
	c := NewSafeCounter()
	var wg sync.WaitGroup
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c.Inc("hits") // safe: serialized by the mutex
		}()
	}
	wg.Wait()
	fmt.Println("hits:", c.Get("hits")) // 1000
}
